patterns.css:
.dvn {
  --dvn-ink: #16150f;
  --dvn-bone: #f2eee6;
  --dvn-olive: #5b6146;
  --dvn-clay: #b07a5a;
  --dvn-line: rgba(22, 21, 15, .16);
  --dvn-gap: clamp(1rem, 3vw, 2.5rem);
  background: var(--dvn-bone);
  color: var(--dvn-ink);
  font-family: 'Manrope', system-ui, sans-serif;
  line-height: 1.5;
  overflow-x: clip;
}
.dvn *, .dvn *::before, .dvn *::after { box-sizing: border-box; }
.dvn img { max-width: 100%; display: block; }
.dvn-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }

.dvn-head {
  position: sticky;
  top: 0;
  z-index: 30;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: var(--dvn-gap);
  padding: .9rem clamp(1rem, 4vw, 3rem);
  background: color-mix(in srgb, var(--dvn-bone) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--dvn-line);
}
.dvn-brand { display: inline-flex; align-items: center; gap: .6rem; color: inherit; text-decoration: none; }
.dvn-brand__mark {
  display: grid;
  place-items: center;
  width: 2.2rem;
  height: 2.2rem;
  border-radius: 50%;
  background: var(--dvn-ink);
  color: var(--dvn-bone);
  font-family: 'Fraunces', Georgia, serif;
  font-size: 1.15rem;
}
.dvn-brand__name { display: flex; flex-direction: column; font-weight: 700; letter-spacing: .02em; line-height: 1; }
.dvn-brand__name small { font-size: .58rem; font-weight: 500; letter-spacing: .22em; text-transform: uppercase; color: var(--dvn-olive); margin-top: .3rem; }
.dvn-nav { display: flex; justify-content: center; gap: clamp(.8rem, 2vw, 1.8rem); font-size: .82rem; letter-spacing: .08em; text-transform: uppercase; }
.dvn-nav a { color: inherit; text-decoration: none; padding: .35rem 0; border-bottom: 1px solid transparent; }
.dvn-nav a:hover, .dvn-nav a:focus-visible { border-color: var(--dvn-ink); }
.dvn-head__actions { display: flex; align-items: center; gap: .75rem; }
.dvn-bag {
  border: 1px solid var(--dvn-ink);
  background: transparent;
  color: inherit;
  border-radius: 999px;
  padding: .45rem .9rem;
  font: inherit;
  font-size: .78rem;
  letter-spacing: .08em;
  text-transform: uppercase;
  cursor: pointer;
}
.dvn-bag span { display: inline-grid; place-items: center; min-width: 1.25rem; height: 1.25rem; margin-left: .35rem; border-radius: 999px; background: var(--dvn-ink); color: var(--dvn-bone); font-size: .7rem; }
.dvn-burger { display: none; width: 2.4rem; height: 2.4rem; border: 1px solid var(--dvn-line); background: transparent; border-radius: 50%; cursor: pointer; }
.dvn-burger span { display: block; width: 1rem; height: 1px; margin: .28rem auto; background: var(--dvn-ink); transition: transform .25s ease; }
.dvn-burger[aria-expanded="true"] span:first-child { transform: translateY(3px) rotate(45deg); }
.dvn-burger[aria-expanded="true"] span:last-child { transform: translateY(-3px) rotate(-45deg); }
.dvn-drawer {
  position: fixed;
  inset: 3.6rem 0 auto;
  z-index: 29;
  display: grid;
  gap: .25rem;
  padding: 1.25rem clamp(1rem, 4vw, 3rem) 2rem;
  background: var(--dvn-bone);
  border-bottom: 1px solid var(--dvn-line);
}
.dvn-drawer a { color: inherit; text-decoration: none; font-size: 1.4rem; font-family: 'Fraunces', Georgia, serif; padding: .35rem 0; }

.dvn-ticker { overflow: hidden; border-bottom: 1px solid var(--dvn-line); background: var(--dvn-ink); color: var(--dvn-bone); }
.dvn-ticker__track { display: flex; gap: 2.5rem; width: max-content; padding: .55rem 0; font-size: .72rem; letter-spacing: .18em; text-transform: uppercase; animation: dvn-run 26s linear infinite; }
.dvn-ticker__track span { white-space: nowrap; }
@keyframes dvn-run { to { transform: translateX(-50%); } }

.dvn-main { padding: 0 clamp(1rem, 4vw, 3rem); }
.dvn-kicker { margin: 0 0 1rem; font-size: .72rem; letter-spacing: .22em; text-transform: uppercase; color: var(--dvn-olive); }
.dvn-h2 { margin: 0; font-family: 'Fraunces', Georgia, serif; font-weight: 500; font-size: clamp(1.8rem, 3.4vw, 2.9rem); letter-spacing: -.02em; }
.dvn-note { margin: .5rem 0 0; max-width: 34ch; color: color-mix(in srgb, var(--dvn-ink) 70%, var(--dvn-bone)); }
.dvn-link { color: inherit; font-size: .8rem; letter-spacing: .1em; text-transform: uppercase; text-decoration: none; border-bottom: 1px solid var(--dvn-ink); padding-bottom: .15rem; }
.dvn-section-head { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--dvn-gap); margin-bottom: clamp(1.2rem, 3vw, 2.4rem); }
.dvn-section-head--inline { align-items: center; }

.dvn-stage {
  display: grid;
  grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr);
  grid-template-areas: "copy collage";
  align-items: center;
  gap: clamp(1.5rem, 5vw, 4rem);
  padding: clamp(2.5rem, 7vw, 6rem) 0 clamp(2rem, 5vw, 4rem);
}
.dvn-stage__copy { grid-area: copy; max-width: 34rem; }
.dvn-title { margin: 0 0 1.25rem; font-family: 'Fraunces', Georgia, serif; font-weight: 400; font-size: clamp(3rem, 8vw, 6.5rem); line-height: .9; letter-spacing: -.04em; }
.dvn-title em { font-style: italic; color: var(--dvn-clay); }
.dvn-lede { margin: 0 0 1.75rem; max-width: 32ch; font-size: clamp(1rem, 1.4vw, 1.12rem); color: color-mix(in srgb, var(--dvn-ink) 78%, var(--dvn-bone)); }
.dvn-row { display: flex; flex-wrap: wrap; gap: .75rem; }
.dvn-btn { display: inline-flex; align-items: center; justify-content: center; padding: .85rem 1.5rem; border-radius: 999px; font-size: .78rem; letter-spacing: .12em; text-transform: uppercase; text-decoration: none; border: 1px solid var(--dvn-ink); cursor: pointer; font-family: inherit; }
.dvn-btn--ink { background: var(--dvn-ink); color: var(--dvn-bone); }
.dvn-btn--ghost { background: transparent; color: var(--dvn-ink); }
.dvn-btn:hover { transform: translateY(-1px); }

.dvn-collage {
  grid-area: collage;
  position: relative;
  display: grid;
  grid-template-columns: 1.2fr .8fr;
  grid-template-rows: repeat(6, 1fr);
  gap: .75rem;
  margin: 0;
  min-height: clamp(24rem, 52vw, 38rem);
}
.dvn-collage__tall {
  grid-column: 1;
  grid-row: 1 / span 6;
  background: linear-gradient(160deg, #d9d2c2 0%, #c2b9a4 55%, #8f866f 100%);
  clip-path: polygon(0 4%, 100% 0, 100% 96%, 0 100%);
}
.dvn-collage__wide {
  grid-column: 2;
  grid-row: 2 / span 3;
  background: linear-gradient(200deg, #6f7558 0%, #4c5239 100%);
}
.dvn-vertical {
  position: absolute;
  right: -.25rem;
  bottom: 0;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: .66rem;
  letter-spacing: .24em;
  text-transform: uppercase;
  color: var(--dvn-olive);
}

.dvn-index { padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-index__list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--dvn-line); }
.dvn-index__list li { border-bottom: 1px solid var(--dvn-line); }
.dvn-index__list a { display: grid; grid-template-columns: 4rem 1fr auto; align-items: baseline; gap: 1rem; padding: clamp(.9rem, 2vw, 1.4rem) 0; color: inherit; text-decoration: none; transition: padding-left .25s ease, color .25s ease; }
.dvn-index__list a:hover, .dvn-index__list a:focus-visible { padding-left: .75rem; color: var(--dvn-olive); }
.dvn-index__n { font-size: .72rem; letter-spacing: .16em; color: var(--dvn-clay); }
.dvn-index__name { font-family: 'Fraunces', Georgia, serif; font-size: clamp(1.4rem, 3vw, 2.2rem); letter-spacing: -.01em; }
.dvn-index__meta { font-size: .74rem; letter-spacing: .12em; text-transform: uppercase; color: var(--dvn-olive); }

.dvn-runway { padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-runway__rail { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(15rem, 22rem); gap: var(--dvn-gap); overflow-x: auto; padding-bottom: 1rem; scroll-snap-type: x mandatory; scrollbar-width: thin; }
.dvn-card { scroll-snap-align: start; display: flex; flex-direction: column; gap: .9rem; }
.dvn-card__media { aspect-ratio: 3 / 4; border-radius: 2px; }
.dvn-card__media--a { background: linear-gradient(150deg, #e3dccd, #b8ad94); }
.dvn-card__media--b { background: linear-gradient(150deg, #8a9070, #4e5539); }
.dvn-card__media--c { background: linear-gradient(150deg, #b9a99c, #7a6558); }
.dvn-card__media--d { background: linear-gradient(150deg, #d5d2cd, #9a968e); }
.dvn-card__body h3 { margin: 0; font-size: .95rem; font-weight: 600; }
.dvn-price { margin: .15rem 0 .6rem; font-size: .85rem; color: var(--dvn-olive); }
.dvn-add { align-self: flex-start; background: none; border: 0; border-bottom: 1px solid var(--dvn-ink); padding: 0 0 .15rem; font: inherit; font-size: .72rem; letter-spacing: .1em; text-transform: uppercase; cursor: pointer; }

.dvn-lookbook { padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-lookbook__grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: var(--dvn-gap); }
.dvn-look { margin: 0; position: relative; display: flex; align-items: flex-end; min-height: clamp(16rem, 30vw, 26rem); }
.dvn-look figcaption { position: relative; z-index: 1; padding: .75rem 1rem; font-size: .72rem; letter-spacing: .12em; text-transform: uppercase; color: var(--dvn-bone); }
.dvn-look--one { grid-column: 1 / span 7; background: linear-gradient(180deg, #c9c2b1, #6f6a59); }
.dvn-look--two { grid-column: 8 / span 5; background: linear-gradient(180deg, #7d8367, #3f452e); margin-top: clamp(1.5rem, 4vw, 3rem); }
.dvn-look--three { grid-column: 3 / span 8; background: linear-gradient(180deg, #b58f76, #6d4c3b); margin-top: calc(var(--dvn-gap) * -0.5); }

.dvn-manifesto { display: grid; grid-template-columns: minmax(0, .8fr) minmax(0, 1.2fr); gap: clamp(1.5rem, 5vw, 4rem); padding: clamp(3rem, 7vw, 6rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-manifesto__side { position: relative; }
.dvn-manifesto__sticky { position: sticky; top: 6rem; margin: 0; font-family: 'Fraunces', Georgia, serif; font-size: clamp(1.35rem, 2.4vw, 1.9rem); line-height: 1.25; letter-spacing: -.01em; }
.dvn-manifesto__body p { margin: 0 0 2rem; max-width: 46ch; color: color-mix(in srgb, var(--dvn-ink) 80%, var(--dvn-bone)); }
.dvn-facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; margin: 0; padding-top: 1.5rem; border-top: 1px solid var(--dvn-line); }
.dvn-facts dt { font-family: 'Fraunces', Georgia, serif; font-size: clamp(1.6rem, 3vw, 2.4rem); }
.dvn-facts dd { margin: .2rem 0 0; font-size: .74rem; letter-spacing: .1em; text-transform: uppercase; color: var(--dvn-olive); }

.dvn-service { padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-service__steps { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--dvn-gap); }
.dvn-service__steps li { padding-top: 1.25rem; border-top: 2px solid var(--dvn-ink); }
.dvn-service__steps span { font-size: .72rem; letter-spacing: .16em; color: var(--dvn-clay); }
.dvn-service__steps h3 { margin: .6rem 0 .4rem; font-family: 'Fraunces', Georgia, serif; font-weight: 500; font-size: 1.4rem; }
.dvn-service__steps p { margin: 0; max-width: 28ch; font-size: .92rem; color: color-mix(in srgb, var(--dvn-ink) 76%, var(--dvn-bone)); }

.dvn-news { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: end; gap: var(--dvn-gap); padding: clamp(2.5rem, 6vw, 5rem) 0; border-top: 1px solid var(--dvn-line); }
.dvn-news__form { display: flex; gap: .6rem; flex-wrap: wrap; }
.dvn-news__form input { flex: 1 1 12rem; min-width: 0; padding: .85rem 1rem; border: 1px solid var(--dvn-line); background: transparent; color: inherit; font: inherit; border-radius: 999px; }
.dvn-news__form input:focus-visible { outline: 2px solid var(--dvn-olive); outline-offset: 2px; }

.dvn-foot { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .5rem; padding: 1.5rem clamp(1rem, 4vw, 3rem); border-top: 1px solid var(--dvn-line); font-size: .72rem; letter-spacing: .1em; text-transform: uppercase; color: var(--dvn-olive); }
.dvn-foot p { margin: 0; }

@media (max-width: 860px) {
  .dvn-nav { display: none; }
  .dvn-burger { display: block; }
  .dvn-stage { grid-template-columns: 1fr; grid-template-areas: "copy" "collage"; }
  .dvn-collage { min-height: 26rem; }
  .dvn-manifesto, .dvn-news { grid-template-columns: 1fr; }
  .dvn-manifesto__sticky { position: static; }
  .dvn-service__steps { grid-template-columns: 1fr; }
  .dvn-look--one, .dvn-look--two, .dvn-look--three { grid-column: 1 / -1; margin-top: 0; }
  .dvn-facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (prefers-reduced-motion: reduce) {
  .dvn-ticker__track { animation: none; }
  .dvn-index__list a, .dvn-btn { transition: none; }
}

