(function () {
  var root = document.querySelector('[data-pattern="daven-indumentaria"]');
  if (!root) return;

  var burger = root.querySelector('[data-dvn-burger]');
  var drawer = root.querySelector('[data-dvn-drawer]');
  if (burger && drawer) {
    burger.addEventListener('click', function () {
      var open = burger.getAttribute('aria-expanded') === 'true';
      burger.setAttribute('aria-expanded', String(!open));
      drawer.hidden = open;
    });
    drawer.addEventListener('click', function (event) {
      if (event.target.tagName === 'A') {
        burger.setAttribute('aria-expanded', 'false');
        drawer.hidden = true;
      }
    });
  }

  var track = root.querySelector('[data-dvn-track]');
  if (track) track.innerHTML += track.innerHTML;

  var count = root.querySelector('[data-dvn-count]');
  root.querySelectorAll('[data-dvn-add]').forEach(function (button) {
    button.addEventListener('click', function () {
      if (!count) return;
      count.textContent = String(Number(count.textContent || 0) + 1);
    });
  });

  var rail = root.querySelector('[data-dvn-rail]');
  if (rail) {
    rail.addEventListener('keydown', function (event) {
      if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return;
      event.preventDefault();
      rail.scrollBy({ left: (event.key === 'ArrowRight' ? 1 : -1) * rail.clientWidth * 0.8, behavior: 'smooth' });
    });
  }

  var form = root.querySelector('.dvn-news__form');
  if (form) {
    form.addEventListener('submit', function (event) {
      event.preventDefault();
      var input = form.querySelector('input[type="email"]');
      if (input && input.checkValidity()) form.reset();
    });
  }
})();

