/* Patrón inspirado en Mercado Libre: barra amarilla, búsqueda blanca,
   acento azul de marketplace, grilla densa de productos con cuotas,
   envío gratis y descuentos. */
:root{
  --ml-yellow:#FFE600;
  --ml-blue:#3483FA;
  --ml-blue-dark:#2968C8;
  --ml-green:#00A650;
  --ml-bg:#EBEBEB;
  --ml-surface:#FFFFFF;
  --ml-ink:#333333;
  --ml-muted:#666666;
  --ml-line:#E0E0E0;
  --ml-radius:8px;
  --ml-font:"Figtree", "Helvetica Neue", Arial, sans-serif;
  --ml-display:"Archivo", "Helvetica Neue", Arial, sans-serif;
  color-scheme: light;
}
*{box-sizing:border-box}
html,body{margin:0}
body{
  background:var(--ml-bg);
  color:var(--ml-ink);
  font:15px/1.45 var(--ml-font);
  -webkit-font-smoothing:antialiased;
}
img{max-width:100%}
button{font:inherit;color:inherit;cursor:pointer}
a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--ml-blue);outline-offset:2px}
.ml-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}

/* HEADER */
.ml-top{background:var(--ml-yellow)}
.ml-top__bar{
  max-width:1200px;margin:0 auto;
  display:grid;grid-template-columns:auto 1fr auto;align-items:center;
  gap:24px;padding:12px 20px 10px;
}
.ml-brand{display:flex;align-items:center;gap:10px;font:800 22px/1 var(--ml-display);letter-spacing:-.02em}
.ml-brand__mark{
  width:34px;height:34px;border-radius:50%;
  background:var(--ml-blue);color:#fff;
  display:grid;place-items:center;font-size:16px;font-weight:800;
}
.ml-brand small{display:block;font:600 10px/1 var(--ml-font);letter-spacing:.16em;text-transform:uppercase;color:#4a4300;margin-top:3px}
.ml-search{display:flex;align-items:center;gap:8px;background:#fff;border-radius:4px;padding:0 12px;height:42px;box-shadow:0 1px 2px rgba(0,0,0,.12)}
.ml-search input{border:0;outline:0;flex:1;font:inherit;background:transparent;color:var(--ml-ink)}
.ml-search button{border:0;background:transparent;display:grid;place-items:center;padding:4px}
.ml-search svg{width:20px;height:20px;stroke:#8a8a8a;fill:none;stroke-width:2}
.ml-top__actions{display:flex;align-items:center;gap:18px;font-size:13px;font-weight:600}
.ml-cart{display:flex;align-items:center;gap:7px;border:0;background:transparent}
.ml-cart svg{width:22px;height:22px;fill:none;stroke:var(--ml-ink);stroke-width:1.8}
.ml-cart span{min-width:20px;height:20px;border-radius:999px;background:var(--ml-blue);color:#fff;font-size:11px;display:grid;place-items:center;padding:0 5px}
.ml-nav{background:#fff;border-bottom:1px solid var(--ml-line)}
.ml-nav__inner{max-width:1200px;margin:0 auto;display:flex;gap:26px;padding:10px 20px;overflow-x:auto;font-size:13px;color:#555;white-space:nowrap}
.ml-nav a:hover{color:var(--ml-blue)}

/* WRAP */
.ml-wrap{max-width:1200px;margin:0 auto;padding:0 20px 72px}
.ml-strip{
  display:flex;align-items:center;justify-content:center;gap:10px;
  background:#fff;border-radius:0 0 var(--ml-radius) var(--ml-radius);
  padding:10px 16px;font-size:13px;font-weight:600;color:#1f5f3f;
}
.ml-strip svg{width:18px;height:18px;stroke:var(--ml-green);fill:none;stroke-width:1.8}

/* HERO */
.ml-hero{
  margin-top:16px;display:grid;grid-template-columns:1.05fr .95fr;
  gap:0;background:linear-gradient(120deg,#1b4f9c,#3483FA 62%,#5aa0ff);
  border-radius:var(--ml-radius);overflow:hidden;color:#fff;
}
.ml-hero__copy{padding:clamp(22px,4vw,48px);display:flex;flex-direction:column;justify-content:center;gap:14px}
.ml-hero__eyebrow{font:700 12px/1 var(--ml-font);letter-spacing:.14em;text-transform:uppercase;color:#FFE600}
.ml-hero h1{margin:0;font:800 clamp(28px,4vw,46px)/1.05 var(--ml-display);letter-spacing:-.02em}
.ml-hero p{margin:0;max-width:38ch;color:#e6efff;font-size:15px}
.ml-hero__cta{align-self:flex-start;margin-top:8px;background:var(--ml-yellow);color:#2b2a00;border:0;border-radius:6px;padding:13px 24px;font-weight:800;font-size:14px}
.ml-hero__cta:hover{background:#ffe93a}
.ml-hero__art{position:relative;min-height:260px;background:
  radial-gradient(120px 120px at 68% 32%,rgba(255,255,255,.35),transparent 70%),
  radial-gradient(220px 220px at 30% 80%,rgba(0,0,0,.18),transparent 70%);}
.ml-hero__art i{position:absolute;display:block;background:rgba(255,255,255,.9);border-radius:10px;box-shadow:0 18px 40px rgba(0,0,0,.18)}
.ml-hero__art i:nth-child(1){width:44%;height:52%;left:12%;top:22%;transform:rotate(-7deg);background:linear-gradient(160deg,#fff,#dfe9fb)}
.ml-hero__art i:nth-child(2){width:36%;height:44%;right:10%;top:12%;transform:rotate(6deg);background:linear-gradient(160deg,#FFE600,#ffd000)}
.ml-hero__art i:nth-child(3){width:30%;height:26%;right:18%;bottom:12%;transform:rotate(-3deg);background:linear-gradient(160deg,#fff,#cfe0ff)}
.ml-hero__art b{
  position:absolute;left:10%;bottom:10%;background:#00A650;color:#fff;
  font:800 13px/1 var(--ml-font);padding:8px 12px;border-radius:999px;transform:rotate(-3deg);
}

/* CATEGORIAS */
.ml-cats{display:grid;grid-template-columns:repeat(7,1fr);gap:10px;margin-top:16px;background:#fff;border-radius:var(--ml-radius);padding:16px 12px}
.ml-cat{display:flex;flex-direction:column;align-items:center;gap:9px;border:0;background:transparent;padding:4px;border-radius:8px}
.ml-cat:hover{background:#f5f5f5}
.ml-cat__icon{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:#eef4ff;color:var(--ml-blue)}
.ml-cat:nth-child(2n) .ml-cat__icon{background:#fff6cc;color:#8a7600}
.ml-cat:nth-child(3n) .ml-cat__icon{background:#e9f8ef;color:#00803d}
.ml-cat__icon svg{width:26px;height:26px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.ml-cat span{font-size:12px;color:#444;text-align:center}

/* SECCIONES */
.ml-section{margin-top:26px}
.ml-section__head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:12px}
.ml-section__head h2{margin:0;font:800 21px/1.2 var(--ml-display);letter-spacing:-.01em}
.ml-section__head a{color:var(--ml-blue);font-size:13px;font-weight:700}

/* OFERTAS */
.ml-offers{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.ml-offer{background:#fff;border-radius:var(--ml-radius);overflow:hidden;display:flex;flex-direction:column;box-shadow:0 1px 2px rgba(0,0,0,.08)}
.ml-offer__media{position:relative;aspect-ratio:16/10;background:linear-gradient(150deg,#eef2f8,#dbe6f7);display:grid;place-items:center}
.ml-offer:nth-child(2) .ml-offer__media{background:linear-gradient(150deg,#fff8d6,#ffeaa0)}
.ml-offer:nth-child(3) .ml-offer__media{background:linear-gradient(150deg,#e8f8ee,#c9efd8)}
.ml-offer:nth-child(4) .ml-offer__media{background:linear-gradient(150deg,#fdeceb,#f9d6d3)}
.ml-offer__media svg{width:54px;height:54px;stroke:#5b6b82;fill:none;stroke-width:1.4}
.ml-offer__badge{position:absolute;left:10px;top:10px;background:var(--ml-green);color:#fff;font:800 12px/1 var(--ml-font);padding:6px 8px;border-radius:4px}
.ml-offer__body{padding:12px 14px 16px;display:flex;flex-direction:column;gap:4px}
.ml-offer__title{font-size:14px;color:#333;margin:0}
.ml-offer__old{margin:0;font-size:12px;color:#999;text-decoration:line-through}
.ml-offer__price{margin:0;font:800 22px/1.1 var(--ml-display);color:#111}
.ml-offer__inst{margin:0;font-size:12px;color:var(--ml-green);font-weight:600}
.ml-offer__ship{margin:0;font-size:12px;color:var(--ml-green);font-weight:700}

/* BENEFICIOS */
.ml-benefits{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:26px}
.ml-benefit{background:#fff;border-radius:var(--ml-radius);padding:16px;display:flex;gap:12px;align-items:flex-start}
.ml-benefit svg{width:26px;height:26px;flex:none;stroke:var(--ml-blue);fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.ml-benefit strong{display:block;font-size:14px;margin-bottom:2px}
.ml-benefit span{font-size:12px;color:var(--ml-muted);line-height:1.35}

/* GRILLA DE PRODUCTOS */
.ml-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:26px;flex-wrap:wrap}
.ml-chips{display:flex;gap:8px;flex-wrap:wrap}
.ml-chip{border:1px solid var(--ml-line);background:#fff;border-radius:999px;padding:7px 14px;font-size:13px;color:#444}
.ml-chip[aria-pressed="true"]{background:#e6efff;border-color:#b9d2fb;color:var(--ml-blue-dark);font-weight:700}
.ml-sort{border:1px solid var(--ml-line);background:#fff;border-radius:6px;padding:8px 10px;font-size:13px;color:#444}
.ml-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:12px}
.ml-card{background:#fff;border-radius:var(--ml-radius);padding:14px;display:flex;flex-direction:column;gap:6px;box-shadow:0 1px 2px rgba(0,0,0,.08);transition:box-shadow .18s ease,transform .18s ease}
.ml-card:hover{box-shadow:0 8px 22px rgba(0,0,0,.12);transform:translateY(-2px)}
.ml-card__media{aspect-ratio:1/1;border-radius:6px;background:linear-gradient(150deg,#f4f6fa,#e3ebf7);display:grid;place-items:center;margin-bottom:6px}
.ml-card__media svg{width:58px;height:58px;stroke:#7a8798;fill:none;stroke-width:1.3}
.ml-card__tag{margin:0;font-size:11px;font-weight:700;color:var(--ml-green);text-transform:uppercase;letter-spacing:.06em}
.ml-card__title{margin:0;font-size:14px;font-weight:500;color:#333;line-height:1.35}
.ml-card__price{margin:2px 0 0;font:800 20px/1.1 var(--ml-display);color:#111}
.ml-card__inst{margin:0;font-size:12px;color:var(--ml-green);font-weight:600}
.ml-card__ship{margin:0;font-size:12px;color:var(--ml-green);font-weight:700}
.ml-card__add{margin-top:8px;border:0;border-radius:6px;background:var(--ml-blue);color:#fff;font-weight:700;font-size:13px;padding:10px}
.ml-card__add:hover{background:var(--ml-blue-dark)}
.ml-empty{margin-top:14px;background:#fff;border-radius:var(--ml-radius);padding:28px;text-align:center;color:var(--ml-muted);display:none}

/* MARCAS */
.ml-brands{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-top:26px}
.ml-brandcard{background:#fff;border-radius:var(--ml-radius);padding:18px 10px;text-align:center;font:800 14px/1 var(--ml-display);color:#8a93a3;letter-spacing:.02em}

/* FAQ */
.ml-faq{margin-top:26px;background:#fff;border-radius:var(--ml-radius);padding:6px 20px}
.ml-faq details{border-bottom:1px solid var(--ml-line);padding:14px 0}
.ml-faq details:last-child{border-bottom:0}
.ml-faq summary{cursor:pointer;font-weight:700;font-size:14px;list-style:none;display:flex;justify-content:space-between;gap:12px}
.ml-faq summary::-webkit-details-marker{display:none}
.ml-faq summary::after{content:"+";color:var(--ml-blue);font-weight:800}
.ml-faq details[open] summary::after{content:"–"}
.ml-faq p{margin:8px 0 0;color:var(--ml-muted);font-size:13px;line-height:1.5}

/* CTA + FOOTER */
.ml-cta{margin-top:26px;background:linear-gradient(110deg,#1b4f9c,#3483FA);border-radius:var(--ml-radius);color:#fff;padding:clamp(22px,3.4vw,40px);display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}
.ml-cta h2{margin:0;font:800 clamp(22px,3vw,30px)/1.15 var(--ml-display)}
.ml-cta p{margin:6px 0 0;color:#dce8ff;font-size:14px}
.ml-cta button{border:0;border-radius:6px;background:var(--ml-yellow);color:#2b2a00;font-weight:800;padding:13px 24px}
.ml-foot{margin-top:26px;background:#fff;border-radius:var(--ml-radius);padding:26px 20px;display:grid;grid-template-columns:repeat(4,1fr);gap:20px;font-size:13px}
.ml-foot h3{margin:0 0 8px;font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:#777}
.ml-foot a{display:block;color:#555;padding:3px 0}
.ml-foot a:hover{color:var(--ml-blue)}
.ml-foot__legal{grid-column:1/-1;border-top:1px solid var(--ml-line);padding-top:14px;color:#8a8a8a;font-size:12px}

/* RESPONSIVE */
@media (max-width:980px){
  .ml-grid,.ml-offers{grid-template-columns:repeat(3,1fr)}
  .ml-cats{grid-template-columns:repeat(4,1fr)}
  .ml-benefits{grid-template-columns:repeat(2,1fr)}
  .ml-brands{grid-template-columns:repeat(3,1fr)}
}
@media (max-width:720px){
  .ml-top__bar{grid-template-columns:auto 1fr;gap:12px}
  .ml-top__actions{display:none}
  .ml-hero{grid-template-columns:1fr}
  .ml-hero__art{min-height:190px}
  .ml-grid,.ml-offers{grid-template-columns:repeat(2,1fr)}
  .ml-cats{grid-template-columns:repeat(4,1fr);gap:4px}
  .ml-cat__icon{width:46px;height:46px}
  .ml-foot{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:420px){
  .ml-grid,.ml-offers{grid-template-columns:1fr}
  .ml-wrap{padding:0 12px 56px}
}
@media (prefers-reduced-motion:reduce){
  *{transition:none!important;animation:none!important}
}

